select u.id,u.username,u.avatar,u.introduction,u.user_status,f.follow_time
from
user as u
left join user_follow as f on u.id=f.followed_user_id
where u.id=#{userId}
and f.user_id=#{currentId}
and f.followed_user_id=#{userId}

select u.id,u.username,u.avatar,u.introduction,u.user_status,f.follow_time
from
user as u
left join user_follow as f on u.id=f.user_id
where u.id=#{userId}
and f.user_id=#{userId}
and f.followed_user_id=#{currentId}

select u.id, u.username, u.avatar, u.introduction, u.user_status,f.follow_time from user as u left join user_follow as f on u.id=f.user_id where u.id in
#{id}
and u.id < lastId
order by f.follow_time desc limit #{pageSize}

select u.id, u.username, u.avatar, u.introduction, u.user_status,f.follow_time from user as u left join user_follow as f on u.id=f.user_id where u.id in
#{id}
order by f.follow_time desc

select u.id, u.username, u.avatar, u.introduction, u.user_status,f.follow_time from user as u left join user_follow as f on u.id=f.followed_user_id left join user_role as ur on u.id=ur.user_id where u.id in
#{id}
and u.id < lastId
and ur.role_id in(1,2) order by f.follow_time desc limit #{pageSize}

select u.id, u.username, u.avatar, u.introduction, u.user_status,f.follow_time from user as u left join user_follow as f on u.id=f.followed_user_id left join user_role as ur on u.id=ur.user_id where u.id in
#{id}
and u.id < lastId
and ur.role_id in (3) order by f.follow_time desc limit #{pageSize}

